def max_sub_array_sum_repeated(arr, n, k):
    if not arr:
        return 0  # Edge case: Empty array

    # Helper to compute maximum subarray sum (Kadane's algorithm)
    def kadane(arr):
        max_sum = float('-inf')
        current_sum = 0
        for num in arr:
            current_sum = max(num, current_sum + num)
            max_sum = max(max_sum, current_sum)
        return max_sum

    max_subarray_sum = kadane(arr)  # Max subarray sum for one instance of arr
    total_sum = sum(arr)           # Total sum of one instance of arr

    # If k == 1, return the max subarray sum of one instance
    if k == 1:
        return max_subarray_sum

    # Compute max_prefix_sum and max_suffix_sum
    max_prefix_sum, max_suffix_sum = float('-inf'), float('-inf')
    current_prefix_sum, current_suffix_sum = 0, 0

    for i in range(n):
        current_prefix_sum += arr[i]
        max_prefix_sum = max(max_prefix_sum, current_prefix_sum)

    for i in range(n - 1, -1, -1):
        current_suffix_sum += arr[i]
        max_suffix_sum = max(max_suffix_sum, current_suffix_sum)

    # If total_sum > 0, include contributions from full repetitions of arr
    if total_sum > 0:
        return max(max_subarray_sum, max_prefix_sum + max_suffix_sum + (k - 2) * total_sum)
    else:
        return max(max_subarray_sum, max_prefix_sum + max_suffix_sum)
