def start_withp(word_list):
    # Collect all words starting with 'p' (case insensitive)
    matches = [
        word for sentence in word_list
        for word in sentence.split()
        if word.lower().startswith('p')
    ]

    # Return the first two matches, or handle edge cases
    if len(matches) >= 2:
        return (matches[0], matches[1])
    elif len(matches) == 1:
        return (matches[0], None)
    else:
        return None

# Example usage and test cases
