def replace_char(input_string, old_char, new_char):
    # Validate input types
    if not isinstance(input_string, str):
        raise TypeError("input_string must be a string")
    if not isinstance(old_char, str) or not isinstance(new_char, str):
        raise TypeError("old_char and new_char must be strings")

    # Validate that old_char is a single character
    if len(old_char) != 1:
        raise ValueError("old_char must be a single character")

    # Validate that new_char is a single character or an empty string
    if len(new_char) > 1:
        raise ValueError("new_char must be a single character or an empty string")

    # Replace all occurrences of old_char with new_char
    return input_string.replace(old_char, new_char)
